const zoomAt = (cx: number, cy: number, factor: number) => {
  setVt((prev) => {
    const z = clampZ(prev.z * factor);
    if (z === prev.z) return prev;
    return { x: cx - ((cx - prev.x) / prev.z) * z, y: cy - ((cy - prev.y) / prev.z) * z, z };
